def generate_all_steel_alborz_items(discount_pct=21.0):
    """
    تولید لیست کامل آیتم‌های کاتالوگ استیل البرز با تبدیل قیمت از ریال به تومان
    و احتساب درصد تخفیف خرید مشخص شده (پیش‌فرض ۲۱٪)
    """
    mult = 1.0 - (discount_pct / 100.0)
    items = []

    for name, cat, rial_price, brand, desc in steel_alborz_raw_items:
        sell_p = rial_price // 10  # تبدیل ریال به تومان
        buy_p = int(round(sell_p * mult))
        items.append({
            'name': name,
            'category': cat,
            'brand': brand,
            'sell_price': sell_p,
            'buy_price': buy_p,
            'description': f'{desc} - تخفیف خرید {discount_pct}%'
        })

    return items


if __name__ == '__main__':
    all_items = generate_all_steel_alborz_items(21.0)
    print(f'Total Steel Alborz items generated: {len(all_items)}')
    sample = all_items[0]
    print('Sample item:', sample)
